// First node MUST verify the bearer credential (same discipline as the
// jobs webhooks). The value lives in the LXC env (/etc/n8n/n8n.env) as
// ALERTS_WEBHOOK_SECRET, never in this JSON. Alertmanager presents it as
// an Authorization: Bearer header (credentials_file in its config).
const req = $input.first().json;
const secret = $env.ALERTS_WEBHOOK_SECRET;
const presented = (req.headers || {})['authorization'];
if (!secret || presented !== `Bearer ${secret}`) {
  return [{ json: { ok: false, error: 'unauthorized' } }];
}
const body = req.body || {};
// Alertmanager webhook payload: {status, groupLabels, alerts: [...]}.
const alerts = (body.alerts || []).map((a) => ({
  status: a.status,
  alertname: a.labels?.alertname ?? 'unknown',
  namespace: a.labels?.namespace ?? '',
  severity: a.labels?.severity ?? '',
  summary: a.annotations?.summary ?? '',
  since: a.startsAt ?? '',
}));
const headline = alerts
  .map((a) => `[${a.status.toUpperCase()}] ${a.alertname}${a.namespace ? ` (${a.namespace})` : ''}: ${a.summary}`)
  .join('\n');
// Terminal channel seam: attach the notification node (email / Telegram /
// push) AFTER this node in the UI, using {{$json.headline}} — then export
// back to n8n/ per the README. Until then, executions in the n8n UI are the
// delivery record.
return [{ json: { ok: true, group_status: body.status ?? '', headline, alerts } }];
